implementation_steps.code_block:
ShellPage_OnPreviewKeyDown or root KeyDown:
    if e.Handled: return
    if e.Key == Escape:
        Send NavigateBackMessage; e.Handled = true
    else if e.Key == Enter and no descendant consumed it:
        Send ActivateSelectedListItemMessage; e.Handled = true

renderedCard.FrameworkElement.KeyDown += OnFormKeyDown;
// retain control-specific handling
// ShellPage handles unhandled Escape/Enter when focus is on the host

openPlaceholderForm();
clickInertContent();
press(Escape); assertListPage();
openPlaceholderForm(); clickInertContent(); press(Enter); assertLaunched();
